local GlassBlowingMoldMaker = {}
local PRODUCTS = {
    iron_glassblowingmold = { name = "Železni model za pihanje stekla", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni model za pihanje stekla za steklarje." },
    bronze_glassblowingmold = { name = "Bronast model za pihanje stekla", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast model za pihanje stekla za steklarje." },
    silver_glassblowingmold = { name = "Srebrn model za pihanje stekla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn model za pihanje stekla za steklarje." },
    gilded_glassblowingmold = { name = "Pozlačen model za pihanje stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen model za pihanje stekla za steklarje." },
    jewel_set_glassblowingmold = { name = "Draguljast model za pihanje stekla", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast model za pihanje stekla za steklarje." },
    royal_sovereign_glassblowingmold = { name = "Kraljevski suveren model za pihanje stekla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren model za pihanje stekla z biseri za krono." },
}
local BUILDINGS = {
    glassblowingmold_workshop = { name = "Glassblowingmold delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassblowingmold_house = { name = "Glassblowingmold hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassblowingmold_atelier = { name = "Mojstrski glassblowingmold atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassblowingmold_palace = { name = "Suverena glassblowingmold palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassBlowingMoldMaker.ironStock=16; GlassBlowingMoldMaker.bronzeStock=12; GlassBlowingMoldMaker.woodStock=12; GlassBlowingMoldMaker.leatherStock=8; GlassBlowingMoldMaker.silverStock=8; GlassBlowingMoldMaker.goldStock=6; GlassBlowingMoldMaker.jewelStock=4; GlassBlowingMoldMaker.pearlStock=4
GlassBlowingMoldMaker.productStock = {}; GlassBlowingMoldMaker.buildings = {}; GlassBlowingMoldMaker.maker = nil; GlassBlowingMoldMaker.activeMaking = {}; GlassBlowingMoldMaker.totalProducts = 0; GlassBlowingMoldMaker.dayTimer = 0
function GlassBlowingMoldMaker.init() GlassBlowingMoldMaker.ironStock=16; GlassBlowingMoldMaker.bronzeStock=12; GlassBlowingMoldMaker.woodStock=12; GlassBlowingMoldMaker.leatherStock=8; GlassBlowingMoldMaker.silverStock=8; GlassBlowingMoldMaker.goldStock=6; GlassBlowingMoldMaker.jewelStock=4; GlassBlowingMoldMaker.pearlStock=4; GlassBlowingMoldMaker.productStock={}; GlassBlowingMoldMaker.buildings={}; GlassBlowingMoldMaker.maker=nil; GlassBlowingMoldMaker.activeMaking={}; GlassBlowingMoldMaker.totalProducts=0; GlassBlowingMoldMaker.dayTimer=0; print("[GlassBlowingMoldMaker] Royal Glass Blowing Mold Maker System initialized (6 products, 4 buildings)") end
function GlassBlowingMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBlowingMoldMaker.maker={name=n or ("Modelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Modelar najet: %s (spretnost: %d)",GlassBlowingMoldMaker.maker.name,s),"success") end; return true end
function GlassBlowingMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBlowingMoldMaker.build(id) local ok,e=GlassBlowingMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBlowingMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBlowingMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBlowingMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBlowingMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassBlowingMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassBlowingMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassBlowingMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassBlowingMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassBlowingMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBlowingMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBlowingMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBlowingMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBlowingMoldMaker.buildings==0 then return false,"Potrebna modelna delavnica" end; if not GlassBlowingMoldMaker.maker then return false,"Potreben modelar" end; return true end
function GlassBlowingMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBlowingMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassBlowingMoldMaker.ironStock=GlassBlowingMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassBlowingMoldMaker.bronzeStock=GlassBlowingMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassBlowingMoldMaker.woodStock=GlassBlowingMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassBlowingMoldMaker.leatherStock=GlassBlowingMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassBlowingMoldMaker.silverStock=GlassBlowingMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBlowingMoldMaker.goldStock=GlassBlowingMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBlowingMoldMaker.jewelStock=GlassBlowingMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBlowingMoldMaker.pearlStock=GlassBlowingMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBlowingMoldMaker.maker then t=math.max(1,t-math.floor(GlassBlowingMoldMaker.maker.skill/13)) end; table.insert(GlassBlowingMoldMaker.activeMaking,{id="glassblowingmold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBlowingMoldMaker.completeMaking(m) local q=1.0+(GlassBlowingMoldMaker.getQualityBonus()/100); if GlassBlowingMoldMaker.maker then q=q+(GlassBlowingMoldMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBlowingMoldMaker.productStock[m.productType]=(GlassBlowingMoldMaker.productStock[m.productType] or 0)+m.quantity; GlassBlowingMoldMaker.totalProducts=GlassBlowingMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBlowingMoldMaker.maker then GlassBlowingMoldMaker.maker.itemsMade=GlassBlowingMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBlowingMoldMaker.maker.skill=math.min(100,GlassBlowingMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassblowingmold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBlowingMoldMaker.update(dt) if not _G.state then return end; GlassBlowingMoldMaker.dayTimer=GlassBlowingMoldMaker.dayTimer+dt; if GlassBlowingMoldMaker.dayTimer>=30 then GlassBlowingMoldMaker.dayTimer=0; for i=#GlassBlowingMoldMaker.activeMaking,1,-1 do local m=GlassBlowingMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBlowingMoldMaker.completeMaking(m); table.remove(GlassBlowingMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBlowingMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBlowingMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBlowingMoldMaker.getStats() return {ironStock=GlassBlowingMoldMaker.ironStock,bronzeStock=GlassBlowingMoldMaker.bronzeStock,woodStock=GlassBlowingMoldMaker.woodStock,leatherStock=GlassBlowingMoldMaker.leatherStock,silverStock=GlassBlowingMoldMaker.silverStock,goldStock=GlassBlowingMoldMaker.goldStock,jewelStock=GlassBlowingMoldMaker.jewelStock,pearlStock=GlassBlowingMoldMaker.pearlStock,productStock=GlassBlowingMoldMaker.productStock,numBuildings=#GlassBlowingMoldMaker.buildings,hasMaker=GlassBlowingMoldMaker.maker~=nil,makerName=GlassBlowingMoldMaker.maker and GlassBlowingMoldMaker.maker.name or "—",makerSkill=GlassBlowingMoldMaker.maker and GlassBlowingMoldMaker.maker.skill or 0,activeMaking=#GlassBlowingMoldMaker.activeMaking,totalProducts=GlassBlowingMoldMaker.totalProducts} end
return GlassBlowingMoldMaker
